type Page = 'overview' | 'history' | 'control' | 'events' | 'settings' | 'debug'
type Unit = 'Pa' | 'mbar' | 'Torr'
type Channel = { channel:number; label:string; pressure_pa:number|null; raw_value:number|null; raw_unit:string; status_code:number|null; status:string; valid:boolean; trip_pa:number|null; reset_pa:number|null }
type Status = { timestamp:string; mode:'simulation'|'real'; interlock:'disarmed'|'ready'|'armed'|'tripped'|'fault'; interlock_label:string; trip_reason:string|null; valve:'unknown'|'open'|'closed'|'opening'|'closing'|'fault'; valve_open_sensor:boolean; valve_closed_sensor:boolean; tpg_connected:boolean; adam_connected:boolean; sample_age_s:number|null; unit:string; permit_ok:boolean; fail_closed_confirmed:boolean; history_recording:boolean; history_error:string|null; channels:Channel[] }
type ChanConfig = { enabled:boolean; label:string; trip_pa:number|null; reset_pa:number|null }
type Config = {
  io_device:'dam0808d'|'adam6050'; dam_serial_port:string; dam_baudrate:number; dam_unit_id:number; external_watchdog_confirmed:boolean; mode:'simulation'|'real'; tpg_connection:'tcp'|'usb'; tpg_serial_port:string; tpg_baudrate:number; tpg_host:string; tpg_port:number; adam_host:string; adam_port:number; adam_unit_id:number
  sample_interval_s:number; stale_timeout_s:number; valve_timeout_s:number; recovery_hold_s:number
  history_retention_days:number|null; allow_lan:boolean; valve_closed_di:number; valve_open_di:number|null
  valve_closed_active_high:boolean; valve_open_active_high:boolean; permit_ok_di:number; permit_ok_active_high:boolean
  watchdog_ok_di:number; watchdog_ok_active_high:boolean; latch_ready_di:number; latch_ready_active_high:boolean
  air_ok_di:number|null; air_ok_active_high:boolean; open_output:number; heartbeat_output:number; reset_output:number
  fail_closed_confirmed:boolean; channels:ChanConfig[]
}
type DebugState = {mode:'real'|'simulation';outputs:boolean[];interlock:string;remaining_s:Record<string,number>}
type EventItem = { id:number; timestamp:string; type:string; severity:string; message:string; actor:string; details:Record<string,unknown> }

const API='/api'
const FACTOR:Record<Unit,number>={Pa:1,mbar:100,Torr:133.32236842105263}
const NAV:{id:Page;label:string;icon:typeof LayoutDashboard}[]=[
  {id:'overview',label:'总览',icon:LayoutDashboard},{id:'history',label:'历史数据',icon:History},
  {id:'control',label:'联锁控制',icon:Shield},{id:'events',label:'事件日志',icon:Bell},{id:'settings',label:'设置',icon:Settings2},{id:'debug',label:'Debug',icon:TerminalSquare},
]

async function api<T>(path:string, init?:RequestInit):Promise<T>{
  const response=await fetch(`${API}${path}`,{credentials:'same-origin',...init,headers:{...(init?.body?{'Content-Type':'application/json'}:{}),...init?.headers}})
  const kind=response.headers.get('content-type')||''
  const data=kind.includes('json')?await response.json():undefined
  if(!response.ok){if(response.status===401)window.dispatchEvent(new Event('auth-needed'));throw new Error(data?.detail||`请求失败 (${response.status})`)}
  return data as T
}
function pressure(value:number|null|undefined,unit:Unit){return value==null||!Number.isFinite(value)?'—':Number((value/FACTOR[unit]).toPrecision(3)).toExponential(2)}
function time(value?:string|null,full=false){if(!value)return'—';return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',second:full?'2-digit':undefined,hour12:false,...(full?{year:'numeric',month:'2-digit',day:'2-digit'}:{})}).format(new Date(value))}
function localValue(date:Date){return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16)}

function Chart({points,channels,unit,compact=false,events=[]}:{points:Point[];channels:number[];unit:Unit;compact?:boolean;events?:EventItem[]}){
  const [view,setView]=useState<[number,number]|null>(null)
  const begin=points.length?Date.parse(points[0].timestamp):0
  const finish=points.length?Date.parse(points[points.length-1].timestamp):1
  const from=Math.max(begin,view?.[0]??begin),to=Math.max(Math.max(begin,view?.[0]??begin),Math.min(finish,view?.[1]??finish))
  const shown=useMemo(()=>reducePoints(points.filter(p=>Date.parse(p.timestamp)>=from&&Date.parse(p.timestamp)<=to)),[points,from,to])
  const [min,max]=domain(shown,channels)
  const w=980,h=compact?260:350,p={l:82,r:22,t:18,b:34},cw=w-p.l-p.r,ch=h-p.t-p.b
  const x=(stamp:string)=>p.l+(Date.parse(stamp)-from)/Math.max(1,to-from)*cw
  const colors=['#b99bff','#67e8cf','#ffcb72','#67a9ff','#ff8d9b','#d4ee83']
  const paths=channels.map(n=>{let active=false;return shown.map(point=>{const c=point.channels.find(c=>c.channel===n);if(!c?.valid||c.pressure_pa==null){active=false;return''}const y=p.t+(1-(Math.log10(Math.max(c.pressure_pa,1e-15))-min)/(max-min))*ch;const d=`${active?'L':'M'}${x(point.timestamp).toFixed(1)} ${y.toFixed(1)}`;active=true;return d}).join(' ')})
  const zoom=(factor:number)=>{const middle=(from+to)/2;const span=Math.max(1000,(to-from)*factor);setView([Math.max(begin,middle-span/2),Math.min(finish,middle+span/2)])}
  const pan=(direction:number)=>{const span=to-from;const start=Math.min(Math.max(begin,from+span*.4*direction),Math.max(begin,finish-span));setView([start,Math.min(finish,start+span)])}
  return <div className={`chart-wrap ${compact?'chart-wrap--compact':''}`}>
    {!compact&&<div className="chart-controls" aria-label="曲线缩放"><button type="button" disabled={!points.length} onClick={()=>zoom(.5)}>放大</button><button type="button" disabled={!points.length} onClick={()=>zoom(2)}>缩小</button><button type="button" disabled={!view} onClick={()=>pan(-1)}>向前</button><button type="button" disabled={!view} onClick={()=>pan(1)}>向后</button><button type="button" onClick={()=>setView(null)}>完整范围</button><small>显示 {shown.length.toLocaleString()} / {points.length.toLocaleString()} 个时间点 · 保留极值</small></div>}
    <svg className="trend-chart" viewBox={`0 0 ${w} ${h}`} role="img" aria-label="真空压力历史曲线">
      {Array.from({length:max-min+1},(_,i)=>max-i).map(e=>{const y=p.t+(1-(e-min)/(max-min))*ch;return <g key={e}><line className="chart-gridline" x1={p.l} x2={w-p.r} y1={y} y2={y}/><text className="chart-axis" x={p.l-10} y={y+4} textAnchor="end">{(10**e/FACTOR[unit]).toExponential(0)}</text></g>})}
      {channels.map((n,i)=><path key={n} d={paths[i]} fill="none" stroke={colors[n-1]} strokeWidth={2.5} strokeLinecap="round"/>)}
      {events.filter(e=>Date.parse(e.timestamp)>=from&&Date.parse(e.timestamp)<=to&&(e.severity==='critical'||e.type==='valve_arrived')).map(e=><g key={e.id}><title>{time(e.timestamp,true)} · {e.message}</title><line x1={x(e.timestamp)} x2={x(e.timestamp)} y1={p.t} y2={p.t+ch} stroke="var(--red)" strokeDasharray="4 5" opacity=".55"/><circle cx={x(e.timestamp)} cy={p.t+4} r="4" fill="var(--red)"/></g>)}
      <text className="chart-axis" x={p.l} y={h-8}>{points.length?time(new Date(from).toISOString()):'等待采样'}</text><text className="chart-axis" x={w-p.r} y={h-8} textAnchor="end">{points.length?time(new Date(to).toISOString()):''}</text>
    </svg>{!points.length&&<div className="chart-empty"><Activity size={18}/>时间范围内没有采样</div>}
    <div className="chart-legend">{channels.map(n=><span key={n}><i style={{background:colors[n-1]}}/>通道 {n}</span>)}</div>
  </div>
}

function Chip({ok,children}:{ok:boolean;children:string}){return <span className={`status-chip ${ok?'status-chip--ok':'status-chip--muted'}`}><i/>{children}</span>}
function PressureCard({channel,unit,mode}:{channel:Channel;unit:Unit;mode:Status['mode']}){
  const near=channel.trip_pa!=null&&channel.pressure_pa!=null&&channel.pressure_pa/channel.trip_pa>.7
  return <article className={`pressure-card glass-panel ${!channel.valid?'pressure-card--bad':near?'pressure-card--near':''}`}>
    <div className="pressure-card__top"><span className="channel-name"><i className="channel-light"/>{channel.label||`通道 ${channel.channel}`}</span><span className={`tiny-badge ${channel.valid?'':'tiny-badge--bad'}`}>{channel.status}</span></div>
    <div className="pressure-value">{pressure(channel.pressure_pa,unit)} <small>{unit}</small></div>
    <div className="pressure-meta"><span>关阀阈值</span><strong>{channel.trip_pa==null?'监测':`${pressure(channel.trip_pa,unit)} ${unit}`}</strong></div>
    {channel.trip_pa!=null&&channel.pressure_pa!=null&&channel.valid&&<div className="threshold-rail"><i style={{width:`${Math.min(100,channel.pressure_pa/channel.trip_pa*100)}%`}}/></div>}
    {mode==='simulation'&&<span className="sim-dot-label">SIM</span>}
  </article>
}
function EventRow({item}:{item:EventItem}){const critical=item.severity==='critical'||item.severity==='error';return <div className={`event-row ${critical?'event-row--critical':''}`}><span className="event-row__time">{time(item.timestamp)}</span><i className={`event-dot ${critical?'event-dot--critical':''}`}/><div className="event-row__body"><b>{item.message}</b><small>{item.actor} · {time(item.timestamp,true)} · {item.type}</small><details><summary>事件详情</summary><pre>{JSON.stringify(item.details,null,2)}</pre></details></div></div>}

function Login({kind,onDone,onClose}:{kind:'setup'|'login';onDone:()=>void;onClose:()=>void}){
  const [password,setPassword]=useState('');const [confirm,setConfirm]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false)
  async function submit(e:FormEvent){e.preventDefault();setError('');if(kind==='setup'&&password!==confirm){setError('两次输入的密码不一致');return}setBusy(true);try{await api(kind==='setup'?'/auth/setup':'/auth/login',{method:'POST',body:JSON.stringify({password})});onDone()}catch(x){setError(x instanceof Error?x.message:'无法登录')}finally{setBusy(false)}}
  return <div className="modal-backdrop" role="dialog" aria-modal="true" aria-label={kind==='setup'?'设置操作员密码':'操作员登录'} onMouseDown={e=>e.target===e.currentTarget&&onClose()}><form className="login-card glass-panel" onSubmit={submit}><button className="icon-button modal-close" aria-label="关闭登录窗口" type="button" onClick={onClose}><X size={17}/></button><div className="brand-mark brand-mark--large"><Shield size={24}/></div><div className="eyebrow">真空保护 · 本地控制</div><h2>{kind==='setup'?'设置操作员密码':'操作员登录'}</h2><p>{kind==='setup'?'首次设置至少 12 位密码。密码只保存在运行设备本机。':'控制与设置需要操作员登录。'}</p><label className="field">密码<input autoFocus type="password" minLength={12} maxLength={256} autoComplete={kind==='setup'?'new-password':'current-password'} value={password} onChange={e=>setPassword(e.target.value)} required/></label>{kind==='setup'&&<label className="field">再次输入<input type="password" minLength={12} value={confirm} onChange={e=>setConfirm(e.target.value)} required/></label>}{error&&<div className="inline-error"><TriangleAlert size={15}/>{error}</div>}<button className="button button--primary login-submit" disabled={busy}>{busy?'正在验证…':kind==='setup'?'保存并登录':'登录控制台'}</button></form></div>
}

function App(){
  const [relayState,setRelayState]=useState<DebugState|null>(null);const [debugError,setDebugError]=useState('');const [debugAcknowledged,setDebugAcknowledged]=useState(false);const [debugDuration,setDebugDuration]=useState(10);const [debugAutoOff,setDebugAutoOff]=useState(false);const [debugBusy,setDebugBusy]=useState(false)
  const [page,setPage]=useState<Page>('overview');const [collapsed,setCollapsed]=useState(()=>localStorage.getItem('vacuum-sidebar')==='closed');const [asideOpen,setAsideOpen]=useState(()=>localStorage.getItem('vacuum-events')!=='closed')
  const [unit,setUnit]=useState<Unit>(()=>(['Pa','mbar','Torr'].includes(localStorage.getItem('vacuum-unit')||'')?localStorage.getItem('vacuum-unit') as Unit:'mbar'));const [theme,setTheme]=useState(()=>localStorage.getItem('vacuum-theme')||'graphite');const [glass,setGlass]=useState(()=>Number(localStorage.getItem('vacuum-glass')||72))
  const [connected,setConnected]=useState(false);const [historyEvents,setHistoryEvents]=useState<EventItem[]>([]);const [eventStart,setEventStart]=useState('');const [eventEnd,setEventEnd]=useState('');const [eventKind,setEventKind]=useState('');const [eventSeverity,setEventSeverity]=useState('');const [eventOffset,setEventOffset]=useState(0);const [eventMore,setEventMore]=useState(false)
  const [status,setStatus]=useState<Status|null>(null);const [events,setEvents]=useState<EventItem[]>([]);const [points,setPoints]=useState<Point[]>([]);const [hist,setHist]=useState<Point[]>([]);const [histCount,setHistCount]=useState<number|null>(null);const [histTruncated,setHistTruncated]=useState(false);const [histReady,setHistReady]=useState(false);const [histBusy,setHistBusy]=useState(false)
  const [resetHistoryOpen,setResetHistoryOpen]=useState(false);const [resetScope,setResetScope]=useState<'simulation'|'all'>('simulation');const [resettingHistory,setResettingHistory]=useState(false)
  const [start,setStart]=useState(()=>localValue(new Date(Date.now()-86400000)));const [end,setEnd]=useState(()=>localValue(new Date()));const [channels,setChannels]=useState([1,2,3,4,5,6]);
  const [draft,setDraft]=useState<Config|null>(null);const [confirm,setConfirm]=useState('');const [auth,setAuth]=useState(false);const [configured,setConfigured]=useState(true);const [local,setLocal]=useState(true);const [login,setLogin]=useState<'setup'|'login'|null>(null);const [toast,setToast]=useState('');const [busy,setBusy]=useState(false)
  const notify=useCallback((message:string)=>{setToast(message);window.setTimeout(()=>setToast(''),4500)},[])
  const refreshStatus=useCallback(async()=>{try{setStatus(await api<Status>('/status'));setConnected(true)}catch{setConnected(false)}},[])
  const refreshEvents=useCallback(async()=>{try{const q=new URLSearchParams({limit:'200',offset:String(eventOffset)});if(eventStart)q.set('start',new Date(eventStart).toISOString());if(eventEnd)q.set('end',new Date(eventEnd).toISOString());if(eventKind)q.set('kind',eventKind);if(eventSeverity)q.set('severity',eventSeverity);const result=await api<{events:EventItem[];has_more:boolean}>(`/events?${q}`);setEvents(result.events);setEventMore(result.has_more)}catch(e){notify(e instanceof Error?e.message:'日志读取失败')}},[eventStart,eventEnd,eventKind,eventSeverity,eventOffset,notify])
  const refreshAuth=useCallback(async()=>{try{const x=await api<{configured:boolean;authenticated:boolean;local:boolean}>('/auth/status');setAuth(x.authenticated);setConfigured(x.configured);setLocal(x.local)}catch{/* server starting */}},[])
  useEffect(()=>{
    void refreshStatus();void refreshAuth();const statusTimer=window.setInterval(()=>void refreshStatus(),1000)
    const authNeeded=()=>{if(local){void refreshAuth();return}setAuth(false);setLogin(configured?'login':null)};window.addEventListener('auth-needed',authNeeded)
    const scheme=location.protocol==='https:'?'wss:':'ws:';let socket:WebSocket|null=null;let retry=0;let cancelled=false
    const connect=()=>{if(cancelled)return;socket=new WebSocket(`${scheme}//${location.host}/ws/status`);socket.onopen=()=>{retry=0;setConnected(true)};socket.onmessage=e=>{try{const s=JSON.parse(e.data) as Status;setStatus(s);setPoints(prior=>[...prior,{timestamp:s.timestamp,channels:s.channels}].slice(-240))}catch{/* ignore malformed frame */}};socket.onclose=()=>{setConnected(false);if(!cancelled)window.setTimeout(connect,Math.min(5000,700+retry++*500))}}
    connect();return()=>{cancelled=true;socket?.close();clearInterval(statusTimer);window.removeEventListener('auth-needed',authNeeded)}
  },[refreshStatus,refreshAuth,configured,local,auth])
  useEffect(()=>{void refreshEvents();const timer=window.setInterval(()=>void refreshEvents(),7000);return()=>clearInterval(timer)},[refreshEvents])
  useEffect(()=>{document.documentElement.dataset.theme=theme;document.documentElement.style.setProperty('--glass-alpha',String(glass/1000));localStorage.setItem('vacuum-theme',theme);localStorage.setItem('vacuum-glass',String(glass))},[theme,glass])
  useEffect(()=>{localStorage.setItem('vacuum-unit',unit)},[unit])
  useEffect(()=>{localStorage.setItem('vacuum-sidebar',collapsed?'closed':'open')},[collapsed])
  useEffect(()=>{localStorage.setItem('vacuum-events',asideOpen?'open':'closed')},[asideOpen])
  useEffect(()=>{if(!login)return;const key=(e:KeyboardEvent)=>{if(e.key==='Escape')setLogin(null)};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key)},[login])
  useEffect(()=>{if(page==='settings')void loadConfig();if(page==='events')void refreshEvents();if(page==='history'&&!histReady)void loadHistory();void refreshAuth();/* eslint-disable-next-line react-hooks/exhaustive-deps */},[page])
  async function loadConfig(){try{const x=await api<{config:Config}>('/config');setDraft(x.config)}catch(e){notify(e instanceof Error?e.message:'无法读取设置')}}
  async function loadHistory(){if(!start||!end||!channels.length){setHist([]);setHistCount(0);setHistReady(false);notify('请选择有效时间范围和至少一个通道');return}if(new Date(end)<=new Date(start)){notify('结束时间必须晚于开始时间');return}setHistBusy(true);try{const q=new URLSearchParams({start:new Date(start).toISOString(),end:new Date(end).toISOString(),channels:channels.join(','),limit:'100000'});const r=await api<{rows:Array<Record<string,unknown>>;count:number;truncated:boolean}>(`/history?${q}`);const grouped=new Map<string,Point>();for(const row of r.rows){const key=String(row.timestamp);let p=grouped.get(key);if(!p){p={timestamp:key,channels:[]};grouped.set(key,p)}p.channels.push({channel:Number(row.channel),pressure_pa:row.pressure_pa==null?null:Number(row.pressure_pa),valid:Boolean(row.valid),mode:row.mode==='real'?'real':'simulation'})}setHist([...grouped.values()]);const ev=await api<{events:EventItem[]}>(`/events?${new URLSearchParams({start:new Date(start).toISOString(),end:new Date(end).toISOString(),limit:'1000'})}`);setHistoryEvents(ev.events);setHistCount(r.count);setHistTruncated(r.truncated);setHistReady(true)}catch(e){notify(e instanceof Error?e.message:'读取历史失败')}finally{setHistBusy(false)}}
  async function act(path:string,success:string){setBusy(true);try{setStatus(await api<Status>(path,{method:'POST',body:'{}'}));await refreshEvents();notify(success)}catch(e){notify(e instanceof Error?e.message:'操作失败')}finally{setBusy(false)}}
  const livePoints=useMemo(()=>points,[points]);const active=status?.channels||[];const highest=active.filter(c=>c.valid&&c.pressure_pa!=null).reduce<Channel|null>((best,c)=>!best||(c.pressure_pa||0)>(best.pressure_pa||0)?c:best,null)
  const patch=(key:keyof Config,value:unknown)=>setDraft(cur=>{if(!cur)return cur;if(key==='mode'&&value==='real'&&cur.mode!=='real')return{...cur,mode:'real',fail_closed_confirmed:false,channels:cur.channels.map(ch=>({...ch,enabled:false,trip_pa:null,reset_pa:null}))};return{...cur,[key]:value} as Config})
  const editChannel=(i:number,key:keyof ChanConfig,value:unknown)=>setDraft(cur=>{if(!cur)return cur;const cs=[...cur.channels];cs[i]={...cs[i],[key]:value};return{...cur,channels:cs}})
  async function saveSettings(){if(!draft)return;if(draft.mode==='real'&&draft.fail_closed_confirmed&&confirm!=='现场确认'){notify('请先输入“现场确认”后保存真实硬件确认');return}setBusy(true);try{const body={...draft,fail_closed_confirmed:draft.mode==='real'&&draft.fail_closed_confirmed&&confirm==='现场确认'};const r=await api<{config:Config;restart_required:boolean}>('/config',{method:'PUT',body:JSON.stringify({config:body})});setDraft(r.config);setConfirm('');notify(r.restart_required?'已保存。切换局域网监听需要重启后台。':'设置已保存，请核对状态后人工复位或启用联锁。');void refreshStatus()}catch(e){notify(e instanceof Error?e.message:'保存失败')}finally{setBusy(false)}}
  async function logOut(){try{await api('/auth/logout',{method:'POST'});setAuth(false);notify('已退出操作员会话')}catch(e){notify(e instanceof Error?e.message:'退出失败')}}
  async function connectSync(){setBusy(true);try{const r=await api<{ok:boolean;tpg?:{ok:boolean;error?:string};adam?:{ok:boolean;error?:string}}>('/devices/connect',{method:'POST',body:'{}'});if(!r.ok)throw new Error(`设备连接失败：${[r.tpg?.error,r.adam?.error].filter(Boolean).join('；')}`);const s=await api<{relays:unknown[]}>('/devices/sync-setpoints',{method:'POST',body:'{}'});await refreshStatus();await refreshEvents();notify(`${s.relays.length} 路继电器阈值已读回验证。`)}catch(e){notify(e instanceof Error?e.message:'设备检查失败')}finally{setBusy(false)}}
  async function simPressure(high:boolean){try{setStatus(await api<Status>('/simulation/pressure',{method:'POST',body:JSON.stringify({channel:1,pressure_pa:high?0.02:0.001})}));notify(high?'已注入通道 1 压力超限':'通道 1 压力已恢复')}catch(e){notify(e instanceof Error?e.message:'模拟操作失败')}}
  async function simFault(kind:'io'|'gauge'|'sensor'|'close'|'tpg',enabled:boolean){try{setStatus(await api<Status>('/simulation/fault',{method:'POST',body:JSON.stringify({kind,enabled,channel:1})}));notify(enabled?'已注入模拟故障':'模拟故障已恢复')}catch(e){notify(e instanceof Error?e.message:'模拟操作失败')}}
  async function resetHistory(){
    setResettingHistory(true)
    try{
      const result=await api<{deleted:number}>('/history/reset',{method:'POST',body:JSON.stringify({scope:resetScope})})
      setHist([]);setHistoryEvents([]);setHistCount(0);setHistTruncated(false);setHistReady(false)
      if(resetScope==='all')setPoints([])
      setResetHistoryOpen(false)
      await loadHistory();await refreshEvents()
      notify(`已清除 ${result.deleted.toLocaleString()} 条${resetScope==='simulation'?'模拟':'压力'}记录，采集继续运行`)
    }catch(e){notify(e instanceof Error?e.message:'历史重置失败')}
    finally{setResettingHistory(false)}
  }
  const refreshRelays=useCallback(async()=>{
    try{setRelayState(await api<DebugState>('/debug/relays'));setDebugError('')}
    catch(e){setRelayState(null);setDebugError(e instanceof Error?e.message:'继电器读取失败')}
  },[])
  useEffect(()=>{
    if(page!=='debug'||!auth)return
    void refreshRelays();const timer=window.setInterval(()=>void refreshRelays(),1000)
    return()=>clearInterval(timer)
  },[page,auth,refreshRelays])
  async function switchRelay(channel:number,enabled:boolean){
    setDebugBusy(true)
    try{setRelayState(await api<DebugState>(`/debug/relays/${channel}`,{method:'POST',body:JSON.stringify({enabled,duration_s:debugAutoOff?debugDuration:0})}));setDebugError('');notify(`OUT${channel+1} 已${enabled?'开启':'关闭'}`)}
    catch(e){const message=e instanceof Error?e.message:'控制失败';await refreshRelays();setDebugError(message);notify(message)}
    finally{setDebugBusy(false)}
  }
  const interlockClass=status?.interlock==='armed'?'armed':status?.interlock==='tripped'||status?.interlock==='fault'?'tripped':'idle'
  const exportUrl=()=>`${API}/history/export.csv?${new URLSearchParams({start:new Date(start).toISOString(),end:new Date(end).toISOString(),channels:channels.join(','),unit})}`

  return <div className={`app-shell ${collapsed?'app-shell--collapsed':''} ${asideOpen?'':'app-shell--events-closed'}`}>
    <aside className={`sidebar glass-panel ${collapsed?'sidebar--collapsed':''}`}><div className="brand-row"><div className="brand-mark"><Gauge size={20}/></div>{!collapsed&&<div className="brand-copy"><b>VACUUM</b><span>INTERLOCK SYSTEM</span></div>}<button className="icon-button sidebar-toggle" aria-label={collapsed?'展开导航':'折叠导航'} aria-expanded={!collapsed} aria-controls="primary-navigation" title={collapsed?'展开导航':'折叠导航'} onClick={()=>setCollapsed(value=>!value)}><Menu size={17}/></button></div>
      <div className="side-kicker">工作区</div><nav id="primary-navigation" className="nav-list" aria-label="主导航">{NAV.map(({id,label,icon:Icon})=><button key={id} className={`nav-item ${page===id?'nav-item--active':''}`} onClick={()=>setPage(id)} title={collapsed?label:undefined}><Icon size={18}/><span>{label}</span>{id==='events'&&events.some(e=>e.severity==='critical')&&<i className="nav-alert"/>}</button>)}</nav><div className="sidebar-spacer"/><div className="side-kicker">当前设备</div><div className="device-mini"><i className={`device-mini__led ${status?.tpg_connected?'is-on':''}`}/>{!collapsed&&<div><b>TPG 366</b><small>{status?.mode==='simulation'?'模拟环境':status?.tpg_connected?'已连接':'等待连接'}</small></div>}</div>
      {local?<div className="user-row"><span className="user-avatar">PC</span>{!collapsed&&<span className="user-copy"><b>本机控制</b><small>无需登录</small></span>}</div>:<><button className="user-row" onClick={()=>auth?void logOut():setLogin(configured?'login':local?'setup':null)} title={collapsed?'操作员账户':undefined}><span className="user-avatar">{auth?'OP':<LockKeyhole size={16}/>}</span>{!collapsed&&<span className="user-copy"><b>{auth?'操作员已登录':'操作员登录'}</b><small>{auth?'退出操作员会话':'需验证后控制'}</small></span>}{!collapsed&&(auth?<LogOut size={15}/>:<ChevronDown size={15}/>)}</button></>}
    </aside>

    <main className="main-column"><header className="topbar glass-panel"><div className="page-heading"><div className="eyebrow">真空保护系统 / {NAV.find(x=>x.id===page)?.label}</div><h1>{page==='overview'?'运行总览':page==='history'?'历史数据':page==='control'?'联锁控制':page==='events'?'事件日志':page==='debug'?'Debug 继电器调试':'设备与系统设置'}</h1></div><div className="topbar-right"><button className="icon-button mobile-menu-toggle" aria-label={collapsed?'展开导航':'折叠导航'} aria-expanded={!collapsed} onClick={()=>setCollapsed(value=>!value)}><Menu size={18}/></button><button className="icon-button" aria-label={asideOpen?'收起事件栏':'展开事件栏'} aria-expanded={asideOpen} onClick={()=>setAsideOpen(value=>!value)}><Bell size={16}/></button><label className="unit-select"><span>压力单位</span><select value={unit} onChange={e=>setUnit(e.target.value as Unit)}><option>Pa</option><option>mbar</option><option>Torr</option></select></label><div className="clock-chip"><Clock3 size={15}/><span>{time(status?.timestamp)}</span><small>北京时间</small></div><button className={`live-pill ${connected&&status?.tpg_connected?'live-pill--on':''}`} onClick={()=>void refreshStatus()}><i/>{!connected?'后台断连':status?.tpg_connected?'采集在线':'等待数据'}</button></div></header>
      {status?.mode==='simulation'&&<div className="sim-banner glass-panel"><span className="sim-banner__badge">SIMULATION</span><span>模拟运行 · 示例阈值只用于演示，切换真实模式后必须填写实验室阈值。</span><button onClick={()=>setPage('settings')}>设备设置 <ChevronDown size={14}/></button></div>}

      {!connected&&<div className="inline-error connection-warning" role="alert"><TriangleAlert size={17}/>后台连接中断，显示的是最后一次状态。控制已暂停。</div>}{status&&!status.history_recording&&<div className="inline-error connection-warning" role="alert">历史记录故障：{status.history_error||'存储不可用'}</div>}
      {page==='overview'&&<div className="page-content">
        <section className={`interlock-banner glass-panel interlock-banner--${interlockClass}`}><div className="interlock-icon">{interlockClass==='armed'?<ShieldCheck size={23}/>:interlockClass==='tripped'?<ShieldAlert size={23}/>:<Shield size={23}/>}</div><div className="interlock-banner__copy"><span className="eyebrow">分子泵保护状态</span><h2>{status?.interlock_label||'正在连接控制器'}</h2><p>{status?.trip_reason||(status?.interlock==='armed'?'监测通道运行正常，硬件许可链路有效。':'联锁待启用。请核对压力阈值和硬件状态。')}</p></div><div className="interlock-banner__actions">
          {status?.interlock==='armed'?<><button className="button button--quiet" disabled={busy} onClick={()=>void act('/valve/close','关阀命令已发送')}>关阀</button><button className="button button--danger-soft" disabled={busy} onClick={()=>void act('/interlock/disarm','联锁已停用，阀门保持关闭')}>停用联锁</button></>:status?.interlock==='tripped'||status?.interlock==='fault'?<button className="button button--primary" disabled={!connected||busy||!auth} onClick={()=>void act('/interlock/clear-fault','故障已清除，联锁未启用')}>复位（不启用） <RotateCcw size={15}/></button>:<button className="button button--primary" disabled={!connected||busy||!auth} onClick={()=>void act('/interlock/arm','联锁已启用')}>启用联锁 <ShieldCheck size={15}/></button>}{!auth&&!local&&<button className="text-link" onClick={()=>setLogin(configured?'login':local?'setup':null)}>登录后操作</button>}</div><div className="ambient-orb"/></section>
        <section className="metric-grid"><article className="metric-card glass-panel"><div className="metric-card__head"><span>最高通道压力</span><Gauge size={16}/></div><strong>{pressure(highest?.pressure_pa,unit)} <small>{unit}</small></strong><div className="metric-card__foot"><span className="metric-accent">{highest?.label||'等待数据'}</span><span>实时读数</span></div></article>
          <article className="metric-card glass-panel"><div className="metric-card__head"><span>插板阀位置</span><Workflow size={16}/></div><strong className={`valve-readout valve-readout--${status?.valve||'unknown'}`}>{status?.valve==='closed'?'已关闭':status?.valve==='open'?'已打开':status?.valve==='opening'?'正在打开':status?.valve==='closing'?'正在关闭':status?.valve==='fault'?'反馈冲突':'未确认'}</strong><div className="metric-card__foot"><span>{status?.valve_closed_sensor?'关闭到位反馈正常':status?.valve_open_sensor?'打开到位反馈正常':'由位置传感器确认'}</span></div></article>
          <article className="metric-card glass-panel"><div className="metric-card__head"><span>保护通道</span><Radio size={16}/></div><strong>{status?.channels.filter(c=>c.trip_pa!=null).length??'—'} <small>/ 6 路</small></strong><div className="metric-card__foot"><span>任一路超限即关阀</span></div></article>
          <article className="metric-card glass-panel"><div className="metric-card__head"><span>数据延迟</span><Activity size={16}/></div><strong>{status?.sample_age_s==null?'—':<>{(status.sample_age_s*1000).toFixed(0)} <small>ms</small></>}</strong><div className="metric-card__foot"><span>后台 10Hz · 历史 1Hz</span></div></article></section>
        <section className="section-heading"><div><span className="eyebrow">GAUGE MONITOR</span><h2>真空通道</h2></div><span className="section-count">{active.length} 个通道</span></section><section className="pressure-grid">{active.map(c=><PressureCard key={c.channel} channel={c} unit={unit} mode={status?.mode||'simulation'}/>)}</section>
        <div className="overview-lower"><section className="content-panel glass-panel"><div className="panel-heading"><div><span className="eyebrow">PRESSURE TREND</span><h2>实时压力趋势</h2></div><button className="text-link" onClick={()=>setPage('history')}>查看历史 <ChevronDown size={14}/></button></div><Chart points={livePoints} channels={[1,2,3,4,5,6]} unit={unit} compact/></section>
          <section className="content-panel glass-panel device-panel"><div className="panel-heading"><div><span className="eyebrow">HARDWARE LINK</span><h2>设备通信</h2></div><button className="icon-button" onClick={()=>void refreshStatus()}><RefreshCw size={15}/></button></div><div className="device-state-row"><span><i className={`device-led ${status?.tpg_connected?'is-on':''}`}/>TPG 366</span><b>{status?.tpg_connected?'在线':'未连接'}</b></div><div className="device-state-row"><span><i className={`device-led ${status?.adam_connected?'is-on':''}`}/>{draft?.io_device==='adam6050'?'ADAM6050':'DAM0808D'}</span><b>{status?.adam_connected?'在线':'未连接'}</b></div><div className="device-state-row"><span><i className={`device-led ${status?.permit_ok?'is-on':''}`}/>硬件许可</span><b>{status?.permit_ok?'就绪':'未就绪'}</b></div><div className="device-panel__footer"><span>最近更新</span><b>{time(status?.timestamp,true)}</b></div>{status?.mode==='real'&&!status?.tpg_connected&&<button className="button button--quiet connect-button" disabled={!connected||!auth||busy} onClick={()=>void connectSync()}>连接设备 <Radio size={15}/></button>}</section></div>
        {status?.mode==='simulation'&&<section className="sim-tools glass-panel"><div><span className="eyebrow">SIMULATION CONTROLS</span><h2>演示故障响应</h2><p>模拟模式仅影响虚拟数据，可演示关阀、锁存和人工复位。</p></div><div className="sim-tools__actions"><button className="button button--danger-soft" disabled={!connected||!auth} onClick={()=>void simPressure(true)}><TriangleAlert size={15}/>注入压力超限</button><button className="button button--quiet" disabled={!connected||!auth} onClick={()=>void simPressure(false)}>恢复压力</button><button className="button button--quiet" disabled={!connected||!auth} onClick={()=>void simFault('io',true)}>模拟 I/O 中断</button><button className="button button--quiet" disabled={!connected||!auth} onClick={()=>void simFault('io',false)}>恢复 I/O</button><button className="button button--quiet" disabled={!connected||!auth} onClick={()=>void simFault('gauge',true)}>真空规故障</button><button className="button button--quiet" disabled={!connected||!auth} onClick={()=>void simFault('gauge',false)}>恢复真空规</button><button className="button button--quiet" disabled={!connected||!auth} onClick={()=>void simFault('sensor',true)}>位置反馈冲突</button><button className="button button--quiet" disabled={!connected||!auth} onClick={()=>void simFault('sensor',false)}>恢复反馈</button><button className="button button--quiet" disabled={!connected||!auth} onClick={()=>void simFault('close',true)}>模拟关阀失败</button><button className="button button--quiet" disabled={!connected||!auth} onClick={()=>void simFault('close',false)}>恢复阀动作</button><button className="button button--quiet" disabled={!connected||!auth} onClick={()=>void simFault('tpg',true)}>TPG 通信中断</button><button className="button button--quiet" disabled={!connected||!auth} onClick={()=>void simFault('tpg',false)}>恢复 TPG 通信</button></div></section>}
      </div>}

      {page==='history'&&<div className="page-content"><section className="filter-panel glass-panel"><div className="filter-grid"><label className="field">开始时间<input type="datetime-local" value={start} onChange={e=>{setStart(e.target.value);setHistReady(false)}}/></label><label className="field">结束时间<input type="datetime-local" value={end} onChange={e=>{setEnd(e.target.value);setHistReady(false)}}/></label><div className="field channel-filter"><span className="field-label">显示通道</span><div>{[1,2,3,4,5,6].map(n=><label key={n}><input type="checkbox" checked={channels.includes(n)} onChange={e=>{setChannels(c=>e.target.checked?[...c,n].sort():c.filter(x=>x!==n));setHistReady(false)}}/>CH{n}</label>)}</div></div><div className="filter-buttons"><button className="button button--quiet" disabled={histBusy||resettingHistory} onClick={()=>void loadHistory()}><RefreshCw size={15} className={histBusy?'spin':''}/>{histBusy?'读取中':'查询数据'}</button><a className={`button button--primary ${histCount&&histReady&&channels.length?'':'is-disabled'}`} href={histCount&&histReady&&channels.length?exportUrl():undefined} onClick={e=>(!histCount||!histReady||!channels.length)&&e.preventDefault()}><ArrowDownToLine size={15}/>导出 CSV</a><button className="button button--quiet" disabled={!connected||!auth||histBusy||resettingHistory} onClick={()=>{setResetScope('simulation');setResetHistoryOpen(true)}}>重置历史</button></div></div></section>
        <section className="content-panel glass-panel history-chart-panel"><div className="panel-heading"><div><span className="eyebrow">RECORDED PRESSURE</span><h2>历史真空曲线</h2></div><span className="history-count">{histCount==null?'选择时间范围查询':`${histCount.toLocaleString()} 条${histTruncated?' · 已达到查询上限':''}`}</span></div><Chart key={`${start}-${end}-${histCount}`} points={hist} channels={channels} unit={unit} events={historyEvents}/></section>
        <section className="content-panel glass-panel history-table-panel"><div className="panel-heading"><div><span className="eyebrow">SAMPLE RECORDS</span><h2>采样记录</h2></div><span className="subtle-note">CSV 包含查询范围内全部记录</span></div><div className="table-scroll"><table><thead><tr><th>北京时间</th><th>通道</th><th>压力</th><th>状态</th><th>记录模式</th></tr></thead><tbody>{hist.slice(-80).reverse().flatMap(p=>p.channels.filter(c=>channels.includes(c.channel)).map(c=><tr key={`${p.timestamp}-${c.channel}`}><td>{time(p.timestamp,true)}</td><td>CH{c.channel}</td><td>{pressure(c.pressure_pa,unit)} {unit}</td><td>{c.valid?'正常':'异常'}</td><td>{c.mode==='simulation'?'模拟':'真实'}</td></tr>))}</tbody></table>{histReady&&!histCount&&<div className="empty-state"><Database size={22}/>时间范围内没有记录</div>}</div></section></div>}

      {page==='control'&&<div className="page-content control-page"><section className={`control-hero glass-panel interlock-banner--${interlockClass}`}><div className="control-orbit"><div className="orbit-ring orbit-ring--one"/><div className="orbit-ring orbit-ring--two"/><div className={`orbit-core orbit-core--${status?.valve}`}><Workflow size={48}/></div></div><span className="eyebrow">VALVE CONTROL</span><h2>{status?.valve==='closed'?'插板阀已关闭':status?.valve==='open'?'插板阀已打开':status?.valve==='opening'?'阀门正在打开':status?.valve==='closing'?'阀门正在关闭':status?.valve==='fault'?'阀位反馈冲突':'阀位未确认'}</h2><p>{status?.valve_closed_sensor?'关闭位置传感器已确认。':status?.valve_open_sensor?'打开位置传感器已确认。':'当前阀位未被传感器确认。'}</p><div className="control-hero__chips"><Chip ok={status?.interlock==='armed'}>{status?.interlock_label||'未启用'}</Chip><Chip ok={status?.permit_ok||false}>{status?.permit_ok?'硬件许可正常':'硬件许可未就绪'}</Chip></div></section>
        <section className="control-actions glass-panel"><div className="panel-heading"><div><span className="eyebrow">OPERATOR ACTIONS</span><h2>操作</h2></div><span className="subtle-note">操作结果记入事件日志</span></div><div className="control-action-grid"><button className="action-tile action-tile--close" disabled={!connected||!auth||busy} onClick={()=>void act('/valve/close','关阀命令已发送')}><span><X size={19}/></span><b>关闭插板阀</b><small>任何联锁状态均可发送</small></button><button className="action-tile" disabled={!connected||!auth||busy||status?.interlock!=='armed'||status?.valve!=='closed'} onClick={()=>void act('/valve/open','开阀命令已发送')}><span><ChevronDown size={19}/></span><b>打开插板阀</b><small>要求联锁启用并确认阀门关闭</small></button>{status?.interlock==='armed'?<button className="action-tile action-tile--warning" disabled={!connected||!auth||busy} onClick={()=>void act('/interlock/disarm','联锁已停用，阀门保持关闭')}><span><ShieldAlert size={19}/></span><b>停用联锁</b><small>阀门保持关闭并记录事件</small></button>:status?.interlock==='tripped'||status?.interlock==='fault'?<button className="action-tile action-tile--warning" disabled={!connected||!auth||busy} onClick={()=>void act('/interlock/clear-fault','故障已清除，联锁未启用')}><span><RotateCcw size={19}/></span><b>复位（不启用）</b><small>清除故障，返回未启用；阀位仍以反馈为准</small></button>:<button className="action-tile action-tile--safe" disabled={!connected||!auth||busy} onClick={()=>void act('/interlock/arm','联锁已启用')}><span><ShieldCheck size={19}/></span><b>启用联锁</b><small>后台先检查压力和硬件许可</small></button>}</div></section>
        <section className="content-panel glass-panel"><div className="panel-heading"><div><span className="eyebrow">PROTECTIVE INPUTS</span><h2>保护条件</h2></div></div><div className="protective-grid"><Chip ok={status?.tpg_connected||false}>{status?.tpg_connected?'TPG 366 通信在线':'TPG 366 未连接'}</Chip><Chip ok={status?.adam_connected||false}>{status?.adam_connected?'I/O 控制器通信在线':'I/O 控制器未连接'}</Chip><Chip ok={status?.permit_ok||false}>{status?.permit_ok?'硬件许可正常':'许可回路未就绪'}</Chip><Chip ok={status?.fail_closed_confirmed||false}>{status?.fail_closed_confirmed?'已确认断电关阀':'未确认断电关阀'}</Chip></div></section></div>}

      {page==='events'&&<div className="page-content"><section className="filter-panel glass-panel"><div className="settings-grid"><label className="field">日志开始时间<input type="datetime-local" value={eventStart} onChange={e=>{setEventStart(e.target.value);setEventOffset(0)}}/></label><label className="field">日志结束时间<input type="datetime-local" value={eventEnd} onChange={e=>{setEventEnd(e.target.value);setEventOffset(0)}}/></label><label className="field">事件类型<input value={eventKind} placeholder="例如 pressure_trip" onChange={e=>{setEventKind(e.target.value);setEventOffset(0)}}/></label><label className="field">级别<select value={eventSeverity} onChange={e=>{setEventSeverity(e.target.value);setEventOffset(0)}}><option value="">全部</option>{['info','warning','error','critical'].map(x=><option key={x}>{x}</option>)}</select></label></div></section><section className="content-panel glass-panel full-events"><div className="panel-heading"><div><span className="eyebrow">AUDIT TRAIL</span><h2>系统事件</h2></div><button className="button button--quiet" onClick={()=>void refreshEvents()}><RefreshCw size={15}/>刷新</button></div><div className="event-feed">{events.map(e=><EventRow item={e} key={e.id}/>)}</div>{!events.length&&<div className="empty-state"><Bell size={22}/>事件触发后显示在这里</div>}<div className="pagination"><button className="button" disabled={!eventOffset} onClick={()=>setEventOffset(n=>Math.max(0,n-200))}>上一页</button><span>第 {Math.floor(eventOffset/200)+1} 页</span><button className="button" disabled={!eventMore} onClick={()=>setEventOffset(n=>n+200)}>下一页</button></div></section></div>}

      {page==='settings'&&<div className="page-content settings-page">{!draft?<div className="empty-state glass-panel"><RefreshCw className="spin"/>正在读取设备设置…</div>:<>
        <section className="content-panel glass-panel"><div className="panel-heading"><div><span className="eyebrow">RUNTIME MODE</span><h2>运行方式</h2></div><span className="tiny-badge">真实联锁须手动启用</span></div><div className="mode-switch"><button className={draft.mode==='simulation'?'selected':''} onClick={()=>patch('mode','simulation')}><Activity size={18}/><b>模拟模式</b><small>不向真实硬件发送控制命令</small></button><button className={draft.mode==='real'?'selected mode-switch__real':''} onClick={()=>patch('mode','real')}><TerminalSquare size={18}/><b>真实设备</b><small>需要已接线的设备和现场确认</small></button></div></section>
        <section className="content-panel glass-panel"><div className="panel-heading"><div><span className="eyebrow">CONTROLLER CONNECTION</span><h2>控制器地址</h2></div><span className="subtle-note">使用实验室隔离网络中的设备</span></div><div className="settings-grid"><label className="field">TPG 366 连接方式<select value={draft.tpg_connection} onChange={e=>patch('tpg_connection',e.target.value)}><option value="tcp">以太网 TCP</option><option value="usb">USB 串口</option></select></label>{draft.tpg_connection==='usb'&&<><label className="field">USB 串口<input placeholder="COM3" value={draft.tpg_serial_port} onChange={e=>patch('tpg_serial_port',e.target.value.trim())}/></label><label className="field">USB 波特率<select value={draft.tpg_baudrate} onChange={e=>patch('tpg_baudrate',Number(e.target.value))}>{[9600,19200,38400,57600,115200].map(rate=><option key={rate}>{rate}</option>)}</select></label></>}<label className="field">TPG 366 IP 地址<input value={draft.tpg_host} placeholder="例如 192.168.1.20" onChange={e=>patch('tpg_host',e.target.value)}/></label><label className="field">TPG TCP 端口<input type="number" min="1" max="65535" value={draft.tpg_port} onChange={e=>patch('tpg_port',Number(e.target.value))}/></label><label className="field">I/O 控制器<select value={draft.io_device} onChange={e=>patch('io_device',e.target.value)}><option value="dam0808d">DAM0808D RS485</option><option value="adam6050">ADAM6050 TCP（旧配置）</option></select></label>{draft.io_device==='adam6050'?<><label className="field">ADAM IP<input value={draft.adam_host} onChange={e=>patch('adam_host',e.target.value)}/></label><label className="field">TCP 端口<input type="number" value={draft.adam_port} onChange={e=>patch('adam_port',Number(e.target.value))}/></label><label className="field">设备地址<input type="number" value={draft.adam_unit_id} onChange={e=>patch('adam_unit_id',Number(e.target.value))}/></label></>:<><label className="field">DAM RS485 串口<input placeholder="例如 COM4（须区别于真空规）" value={draft.dam_serial_port} onChange={e=>patch('dam_serial_port',e.target.value.trim())}/></label><label className="field">DAM 波特率<select value={draft.dam_baudrate} onChange={e=>patch('dam_baudrate',Number(e.target.value))}>{[2400,4800,9600,19200,38400].map(rate=><option key={rate}>{rate}</option>)}</select></label><label className="field">DAM 设备地址<input type="number" min="1" max="255" value={draft.dam_unit_id} onChange={e=>patch('dam_unit_id',Number(e.target.value))}/></label></>}<label className="field">历史采样间隔（秒）<input type="number" min="0.2" max="30" step="0.1" value={draft.sample_interval_s} onChange={e=>patch('sample_interval_s',Number(e.target.value))}/></label><label className="field">数据超时保护（秒）<input type="number" min="0.5" max="10" step="0.1" value={draft.stale_timeout_s} onChange={e=>patch('stale_timeout_s',Number(e.target.value))}/></label><label className="field">压力恢复稳定时间（秒）<input type="number" min="0" max="120" step="0.5" value={draft.recovery_hold_s} onChange={e=>patch('recovery_hold_s',Number(e.target.value))}/></label><label className="field">历史保留天数（留空不限）<input type="number" min="1" max="3650" value={draft.history_retention_days??''} onChange={e=>patch('history_retention_days',e.target.value===''?null:Number(e.target.value))}/></label></div><div className="info-line"><Activity size={16}/>DAM 串口使用 8N1，默认 9600 波特；设备地址按拨码及偏移地址填写，禁止广播地址 0。</div></section>
        <section className="content-panel glass-panel"><div className="panel-heading"><div><span className="eyebrow">PRESSURE LIMITS</span><h2>通道与压力阈值</h2></div><span className="subtle-note">达到上限触发，低于恢复值才允许复位</span></div><div className="threshold-table-wrap"><table className="threshold-table"><thead><tr><th>保护</th><th>通道</th><th>名称</th><th>关阀阈值 ({unit})</th><th>恢复阈值 ({unit})</th></tr></thead><tbody>{draft.channels.map((c,i)=><tr key={i}><td><input type="checkbox" checked={c.enabled} aria-label={`启用通道 ${i+1}`} onChange={e=>editChannel(i,'enabled',e.target.checked)}/></td><td>CH{i+1}</td><td><input className="table-input" value={c.label} maxLength={24} placeholder={`通道 ${i+1}`} onChange={e=>editChannel(i,'label',e.target.value)}/></td><td><input className="table-input" type="number" min="0" step="any" value={c.trip_pa==null?'':Number((c.trip_pa/FACTOR[unit]).toPrecision(5))} placeholder="必填" onChange={e=>editChannel(i,'trip_pa',e.target.value===''?null:Number(e.target.value)*FACTOR[unit])}/></td><td><input className="table-input" type="number" min="0" step="any" value={c.reset_pa==null?'':Number((c.reset_pa/FACTOR[unit]).toPrecision(5))} placeholder="必填" onChange={e=>editChannel(i,'reset_pa',e.target.value===''?null:Number(e.target.value)*FACTOR[unit])}/></td></tr>)}</tbody></table></div><div className="info-line"><ShieldCheck size={16}/>多通道实行任一路超限关阀。真实模式须输入实验室设定值；系统不会替你猜安全阈值。</div></section>
        <section className="content-panel glass-panel"><div className="panel-heading"><div><span className="eyebrow">DAM0808D I/O MAP</span><h2>输入输出与 Sensor</h2></div><span className="subtle-note">软件 0–7 对应 DAM 第 1–8 路</span></div><div className="io-map-grid"><label className="field">关闭到位 DI<input type="number" min="0" max={draft.io_device==='dam0808d'?7:11} value={draft.valve_closed_di} onChange={e=>patch('valve_closed_di',Number(e.target.value))}/></label><label className="field">打开到位 DI（可选）<input type="number" min="0" max={draft.io_device==='dam0808d'?7:11} placeholder="未安装" value={draft.valve_open_di??''} onChange={e=>patch('valve_open_di',e.target.value===''?null:Number(e.target.value))}/></label><label className="field">压力许可 DI<input type="number" min="0" max={draft.io_device==='dam0808d'?7:11} value={draft.permit_ok_di} onChange={e=>patch('permit_ok_di',Number(e.target.value))}/></label><label className="field">看门狗正常 DI<input type="number" min="0" max={draft.io_device==='dam0808d'?7:11} value={draft.watchdog_ok_di} onChange={e=>patch('watchdog_ok_di',Number(e.target.value))}/></label><label className="field">锁存就绪 DI<input type="number" min="0" max={draft.io_device==='dam0808d'?7:11} value={draft.latch_ready_di} onChange={e=>patch('latch_ready_di',Number(e.target.value))}/></label><label className="field">气源正常 DI（可选）<input type="number" min="0" max={draft.io_device==='dam0808d'?7:11} placeholder="未安装" value={draft.air_ok_di??''} onChange={e=>patch('air_ok_di',e.target.value===''?null:Number(e.target.value))}/></label><label className="field">开阀请求 DO<input type="number" min="0" max={draft.io_device==='dam0808d'?7:5} value={draft.open_output} onChange={e=>patch('open_output',Number(e.target.value))}/></label><label className="field">旧 ADAM 心跳 DO<input type="number" min="0" max={draft.io_device==='dam0808d'?7:5} value={draft.heartbeat_output} onChange={e=>patch('heartbeat_output',Number(e.target.value))}/></label><label className="field">硬件复位 DO<input type="number" min="0" max={draft.io_device==='dam0808d'?7:5} value={draft.reset_output} onChange={e=>patch('reset_output',Number(e.target.value))}/></label></div><label><input type="checkbox" checked={draft.external_watchdog_confirmed} onChange={e=>patch('external_watchdog_confirmed',e.target.checked)}/>已验证独立硬件看门狗会在通信或程序失效时切断开阀许可（DAM 不输出高频机械心跳）</label><div className="polarity-grid">{([['valve_closed_active_high','关闭传感器高电平有效'],['valve_open_active_high','打开传感器高电平有效'],['permit_ok_active_high','压力许可高电平有效'],['watchdog_ok_active_high','看门狗高电平有效'],['latch_ready_active_high','锁存反馈高电平有效'],['air_ok_active_high','气源信号高电平有效']] as const).map(([key,label])=><label key={key}><input type="checkbox" checked={draft[key]} onChange={e=>patch(key,e.target.checked)}/>{label}</label>)}</div><div className="info-line"><Database size={16}/>DAM 继电器控制电磁阀；感性负载须配置续流或浪涌抑制。Sensor 的线数、电平和动作方向须按随阀附件核对；无开到位反馈时界面显示“未确认”。</div></section>
        {draft.mode==='real'&&<section className="content-panel glass-panel commissioning-panel"><div className="panel-heading"><div><span className="eyebrow">HARDWARE COMMISSIONING</span><h2>真实硬件启用确认</h2></div><span className="tiny-badge tiny-badge--bad">现场验证</span></div><div className="commissioning-note"><AlertOctagon size={20}/><p>确认随货电磁阀在控制失电时会关阀，TPG 压力触点和独立看门狗接入硬件许可回路，并检查传感器极性。</p></div><label className="field confirm-field">现场确认口令<input value={confirm} placeholder="输入：现场确认" onChange={e=>setConfirm(e.target.value)}/></label><label className="check-row"><input type="checkbox" checked={draft.fail_closed_confirmed} onChange={e=>patch('fail_closed_confirmed',e.target.checked)}/>我已完成断电关阀、硬件断线和阀位反馈验证</label></section>}
        <section className="content-panel glass-panel"><div className="panel-heading"><div><span className="eyebrow">NETWORK ACCESS</span><h2>局域网访问</h2></div></div><label className="check-row"><input type="checkbox" checked={draft.allow_lan} onChange={e=>patch('allow_lan',e.target.checked)}/>允许局域网内设备通过 HTTPS 访问控制台</label><div className="info-line"><LockKeyhole size={16}/>本机无需登录。局域网访问仍需操作员密码并信任本机证书；切换监听方式需重启服务。</div></section>
        <div className="settings-footer"><span>修改设备设置会使运行中的联锁进入锁存状态。</span><div><button className="button button--quiet" onClick={()=>void loadConfig()}>放弃更改</button><button className="button button--primary" disabled={!connected||busy||!auth} onClick={()=>void saveSettings()}>{busy?'保存中':'保存设备设置'} <Check size={15}/></button></div></div>
        {draft.mode==='real'&&<section className="real-connection-row glass-panel"><div><b>连接设备并同步继电器</b><span>写入 TPG 366 六路继电器设置，再逐路读回核对。</span></div><button className="button button--quiet" disabled={!connected||!auth||busy} onClick={()=>void act('/devices/connect-gauge','真空规已连接，控制保持未启用')}>仅连接真空规</button><button className="button button--quiet" disabled={!connected||!auth||busy} onClick={()=>void connectSync()}><Radio size={15}/>连接并校验</button></section>}
      </>}</div>}
      {page==='debug'&&<div className="page-content"><section className="content-panel glass-panel"><div className="panel-heading"><div><span className="eyebrow">MANUAL RELAY CONTROL</span><h2>DAM0808D 手动控制</h2></div><button className="button button--quiet" disabled={!auth||debugBusy} onClick={()=>void refreshRelays()}><RefreshCw size={15}/>刷新状态</button></div><p>此处直接控制继电器，不检查真空压力许可。OUT1 可能让电磁阀通电并使插板阀动作。仅用于停机接线调试。</p><p>{relayState?.mode==='simulation'?'当前为模拟模式，不控制真实设备。':'当前为真实设备模式。'}默认保持开启，直到手动关闭；勾选定时关闭才会自动关闭。通信或程序故障时，软件不能保证断电。</p>{!auth&&!local&&<button className="button button--primary" onClick={()=>setLogin(configured?'login':'setup')}>登录后调试</button>}<div className="settings-grid"><label><input type="checkbox" checked={debugAutoOff} onChange={e=>setDebugAutoOff(e.target.checked)}/>定时关闭（可选）</label><label className="field">自动关闭时间（秒）<input type="number" min="1" max="60" disabled={!debugAutoOff} value={debugDuration} onChange={e=>setDebugDuration(Math.max(1,Math.min(60,Number(e.target.value)||1)))}/></label><label><input type="checkbox" checked={debugAcknowledged} onChange={e=>setDebugAcknowledged(e.target.checked)}/>已确认设备可以动作，并已核对接线和线圈电压</label></div>{debugError&&<div className="inline-error" role="alert">{debugError}</div>}{status?.interlock!=='disarmed'&&<p className="inline-error">联锁未处于“未启用”，禁止手动开启。</p>}<div className="debug-relay-grid">{Array.from({length:8},(_,channel)=><article className="glass-panel debug-relay-card" key={channel}><h3>OUT{channel+1} <small>DO{channel}</small></h3><p>{relayState?relayState.outputs[channel]?'已开启':'已关闭':'状态未知'}{relayState?.remaining_s[String(channel)]!=null&&` · ${Math.ceil(relayState.remaining_s[String(channel)])} 秒后关闭`}{relayState?.outputs[channel]&&relayState.remaining_s[String(channel)]==null&&" · 保持开启，等待手动关闭"}</p><div className="filter-buttons"><button className="button button--primary" aria-label={`开启 OUT${channel+1}`} disabled={!connected||!auth||!debugAcknowledged||debugBusy||!relayState||status?.interlock!=='disarmed'||relayState.interlock!=='disarmed'} onClick={()=>void switchRelay(channel,true)}>开启</button><button className="button button--quiet" aria-label={`关闭 OUT${channel+1}`} disabled={!connected||!auth||debugBusy||!relayState} onClick={()=>void switchRelay(channel,false)}>关闭</button></div></article>)}</div></section></div>}
      <footer className="footer"><span>VACUUM INTERLOCK <i/> LOCAL CONTROL SERVICE</span><span>数据保存在本机 · {status?.mode==='simulation'?'模拟模式':'真实设备模式'}</span></footer>
    </main>

    <aside className={`events-aside glass-panel ${asideOpen?'':'events-aside--closed'}`}><div className="aside-heading"><div><span className="eyebrow">SYSTEM LOG</span><h2>最近事件</h2></div><div><button className="icon-button" onClick={()=>void refreshEvents()} title="刷新事件"><RefreshCw size={14}/></button><button className="icon-button" onClick={()=>setAsideOpen(value=>!value)} aria-label={asideOpen?'收起事件栏':'展开事件栏'} aria-expanded={asideOpen} title={asideOpen?'收起事件栏':'展开事件栏'}>{asideOpen?<ChevronDown size={15}/>:<ChevronDown className="rotate-left" size={15}/>}</button></div></div>{asideOpen&&<><div className="event-summary"><span><i className={events.some(e=>e.severity==='critical')?'event-summary__alert':''}/>{events.some(e=>e.severity==='critical')?'有联锁事件':'运行事件'}</span><button onClick={()=>setPage('events')}>全部 <ChevronDown size={13}/></button></div><div id="recent-events" className="aside-events">{events.slice(0,18).map(e=><EventRow item={e} key={e.id}/>)}{!events.length&&<div className="event-empty"><Check size={16}/>暂无事件</div>}</div><div className="aside-footer"><Database size={14}/>历史与日志保存在本机</div></>}</aside>
    <div className="mobile-nav">{NAV.map(({id,label,icon:Icon})=><button key={id} onClick={()=>setPage(id)}><Icon size={18}/><span>{label==='联锁控制'?'控制':label==='历史数据'?'历史':label==='设备与系统设置'?'设置':label==='事件日志'?'事件':label}</span></button>)}</div>
    <button className="theme-fab" aria-label="切换主题" title="切换主题" onClick={()=>setTheme(theme==='graphite'?'light':'graphite')}><SlidersHorizontal size={16}/></button>{page==='settings'&&<div className="glass-adjuster"><label>玻璃强度<input type="range" min="25" max="100" value={glass} onChange={e=>setGlass(Number(e.target.value))}/></label></div>}
    {resetHistoryOpen&&<div className="modal-backdrop"><section className="login-card glass-panel" role="dialog" aria-modal="true" aria-labelledby="history-reset-title"><h2 id="history-reset-title">重置压力历史</h2><p>清除范围不受当前时间或通道筛选限制。操作不可撤销，采集会继续，事件日志保留。</p><label className="field">重置范围<select value={resetScope} disabled={resettingHistory} onChange={e=>setResetScope(e.target.value as 'simulation'|'all')}><option value="simulation">仅清除模拟数据（保留真实数据）</option><option value="all">清除全部压力数据（包含真实数据）</option></select></label><div className="filter-buttons"><button className="button button--quiet" disabled={resettingHistory} onClick={()=>setResetHistoryOpen(false)}>取消</button><button className="button button--primary" disabled={resettingHistory||!connected||!auth} onClick={()=>void resetHistory()}>{resettingHistory?'重置中':'确认重置'}</button></div></section></div>}
    {toast&&<div className="toast-message" role="status"><span><Check size={16}/></span>{toast}<button onClick={()=>setToast('')}><X size={15}/></button></div>}{login&&<Login kind={login} onClose={()=>setLogin(null)} onDone={()=>{setAuth(true);setConfigured(true);setLogin(null);notify('操作员已登录');void refreshStatus()}}/>}
  </div>
}

export default App
